// --- Lead scoring logic ---
// Adjust weights/thresholds to match your business rules.
const item = items[0].json;

let score = 0;

// Budget signal (0-50 points)
if (item.budget >= 10000) score += 50;
else if (item.budget >= 5000) score += 35;
else if (item.budget >= 1000) score += 20;
else if (item.budget > 0) score += 10;

// Urgency signal (0-30 points)
const urgency = String(item.urgency).toLowerCase();
if (urgency === 'high' || urgency === 'urgent') score += 30;
else if (urgency === 'medium') score += 15;
else if (urgency === 'low') score += 5;

// Timeline signal (0-20 points) - sooner start = higher score
if (item.timeline_weeks <= 2) score += 20;
else if (item.timeline_weeks <= 6) score += 10;
else if (item.timeline_weeks <= 12) score += 5;

score = Math.min(score, 100);
const category = score >= 60 ? 'Hot' : 'Cold';

return [{
  json: {
    ...item,
    lead_score: score,
    lead_category: category
  }
}];

